#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_HANDLERS 32
#define MAX_MSG_LEN 4096
#define HANDLER_PATH_MAX 256

typedef void (*ws_handler_fn)(const char *payload, int client_fd);

struct handler_entry {
    char name[64];
    ws_handler_fn fn;
    void *dl_handle;
};

static struct handler_entry g_handlers[MAX_HANDLERS];
static int g_handler_count = 0;
static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;

static int validate_handler_name(const char *name) {
    if (!name || strlen(name) == 0 || strlen(name) > 63) return 0;
    for (const char *p = name; *p; p++) {
        if (!((*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
              (*p >= '0' && *p <= '9') || *p == '_')) return 0;
    }
    return 1;
}

static char *get_handler_base_path(void) {
    char *path = getenv("WS_HANDLER_PATH");
    if (path && strlen(path) > 0) return path;
    return "/usr/lib/ws_handlers";
}

static int resolve_handler_path(const char *name, char *out, size_t out_sz) {
    const char *base = get_handler_base_path();
    int written = snprintf(out, out_sz, "%s/%s.so", base, name);
    if (written < 0 || (size_t)written >= out_sz) return -1;
    return 0;
}

static ws_handler_fn load_handler(const char *name) {
    if (!validate_handler_name(name)) return NULL;

    pthread_mutex_lock(&g_lock);
    for (int i = 0; i < g_handler_count; i++) {
        if (strcmp(g_handlers[i].name, name) == 0) {
            pthread_mutex_unlock(&g_lock);
            return g_handlers[i].fn;
        }
    }

    if (g_handler_count >= MAX_HANDLERS) {
        pthread_mutex_unlock(&g_lock);
        return NULL;
    }

    char path[HANDLER_PATH_MAX];
    if (resolve_handler_path(name, path, sizeof(path)) != 0) {
        pthread_mutex_unlock(&g_lock);
        return NULL;
    }

    void *handle = dlopen(path, RTLD_NOW | RTLD_LOCAL);
    if (!handle) {
        pthread_mutex_unlock(&g_lock);
        return NULL;
    }

    char sym_name[128];
    snprintf(sym_name, sizeof(sym_name), "handle_%s", name);
    ws_handler_fn fn = (ws_handler_fn)dlsym(handle, sym_name);
    if (!fn) {
        dlclose(handle);
        pthread_mutex_unlock(&g_lock);
        return NULL;
    }

    strncpy(g_handlers[g_handler_count].name, name, 63);
    g_handlers[g_handler_count].name[63] = '\0';
    g_handlers[g_handler_count].fn = fn;
    g_handlers[g_handler_count].dl_handle = handle;
    g_handler_count++;

    pthread_mutex_unlock(&g_lock);
    return fn;
}

static void dispatch_message(const char *msg, int client_fd) {
    char handler_name[64];
    char payload[MAX_MSG_LEN];

    const char *sep = strchr(msg, ':');
    if (!sep) return;

    size_t name_len = sep - msg;
    if (name_len >= sizeof(handler_name)) return;
    memcpy(handler_name, msg, name_len);
    handler_name[name_len] = '\0';

    strncpy(payload, sep + 1, MAX_MSG_LEN - 1);
    payload[MAX_MSG_LEN - 1] = '\0';

    ws_handler_fn fn = load_handler(handler_name);
    if (fn) {
        fn(payload, client_fd);
    }
}

static void *client_thread(void *arg) {
    int fd = *(int *)arg;
    free(arg);
    char buf[MAX_MSG_LEN];

    while (1) {
        ssize_t n = recv(fd, buf, sizeof(buf) - 1, 0);
        if (n <= 0) break;
        buf[n] = '\0';
        dispatch_message(buf, fd);
    }
    close(fd);
    return NULL;
}

int main(int argc, char *argv[]) {
    int port = 8080;
    char *env_port = getenv("WS_PORT");
    if (env_port) port = atoi(env_port);

    int srv = socket(AF_INET, SOCK_STREAM, 0);
    if (srv < 0) { perror("socket"); return 1; }

    int opt = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(srv, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); return 1;
    }
    listen(srv, 16);
    printf("WebSocket server on port %d, handler path: %s\n", port, get_handler_base_path());

    while (1) {
        int *cfd = malloc(sizeof(int));
        *cfd = accept(srv, NULL, NULL);
        if (*cfd < 0) { free(cfd); continue; }
        pthread_t t;
        pthread_create(&t, NULL, client_thread, cfd);
        pthread_detach(t);
    }
    return 0;
}
